import { Link } from 'react-router-dom';

/**
 * The official Cambuz icon, rendered from the PNG set generated by
 * scripts/generate-icon-assets.py. The artwork is never redrawn or recoloured
 * for the web — see assets/icon-master.png.
 */
export function BrandMark({
  size = 36,
  className = '',
}: {
  size?: number;
  className?: string;
}) {
  return (
    <img
      src="/icons/logo-mark-128.png"
      srcSet="/icons/logo-mark-128.png 1x, /icons/logo-mark-256.png 2x"
      width={size}
      height={size}
      alt=""
      aria-hidden="true"
      decoding="async"
      className={`flex-shrink-0 ${className}`}
    />
  );
}

/**
 * Header lockup: the official mark plus the wordmark as real HTML text, so it
 * stays crisp at every zoom level, is selectable and is readable to search
 * engines and screen readers.
 */
export function Logo({ className = '' }: { className?: string }) {
  return (
    <Link
      to="/"
      className={`flex items-center gap-2.5 group ${className}`}
      aria-label="Cambuz PDF Reader home"
    >
      <BrandMark size={36} className="transition-transform duration-200 group-hover:scale-105" />
      <span className="text-lg font-semibold tracking-tight text-text-main group-hover:text-white transition-colors">
        Cambuz
      </span>
    </Link>
  );
}
